using System.IO; using System.Text.Json; using System.Windows; using System.Windows.Automation; using System.Windows.Controls; using System.Windows.Media; using LifeOS.Core.ConfigurationReadiness; using LifeOS.Core.ConnectionHealth; using LifeOS.Core.Forms; using LifeOS.Shared.ConnectionHealth; using LifeOS.Shared.Storage;
namespace LifeOS.Desktop;
public sealed class ConnectionHealthWorkspaceView : UserControl
{
    private readonly bool _demo; private List<ConnectionHealthRecord> _records=[]; private IReadOnlyList<FormFieldIssue> _issues=[]; private UserFacingProblem? _problem; private string? _notice; private string _capability="",_owner="",_reference="",_notes=""; private ConfigurationEnvironment _environment; private ConnectionCheckKind _kind;
    public ConnectionHealthWorkspaceView(bool demo){_demo=demo;Background=B("#0C1220");Foreground=Brushes.White;FontFamily=new("Segoe UI");try{_records=ConnectionHealthStorage.Load();}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or JsonException){_problem=UserFacingProblemFactory.FromException(ex,"load connection health");}Render();}
    private void Render(){StackPanel root=new(){Margin=new(24)};root.Children.Add(T(_demo?"PORTFOLIO DEMO • ISOLATED":"ORDINARY MODE • NO CONNECTIONS RUN",11,"#AFA4FF",FontWeights.SemiBold));root.Children.Add(T("Connection Testing & Health Diagnostics",30,"#FFFFFF",FontWeights.Bold));root.Children.Add(T("Prepare credentialed checks and record explicit observations. This configuration-free surface never opens a network connection, reads a secret value or calls a provider.",14,"#B8C5D8"));if(_notice!=null)root.Children.Add(T(_notice,12,"#83D4B3",FontWeights.SemiBold));if(_problem!=null)root.Children.Add(Problem(_problem));WrapPanel m=new(){Margin=new(0,16,0,8)};m.Children.Add(Metric("Diagnostic plans",_records.Count.ToString(),"Local metadata"));m.Children.Add(Metric("Not configured",_records.Count(x=>x.State==ConnectionHealthState.NotConfigured).ToString(),"Reference missing"));m.Children.Add(Metric("Ready to test",_records.Count(x=>x.State==ConnectionHealthState.ReadyForCredentialedTest).ToString(),"No test implied"));m.Children.Add(Metric("Connections run","0","Hard boundary"));root.Children.Add(m);root.Children.Add(Capture());root.Children.Add(H("Health records",21,new(0,20,0,6)));if(_records.Count==0)root.Children.Add(Card("No diagnostic plans yet","Ordinary mode starts empty. Add reference names and ownership without credentials or endpoints.","#151F30"));else foreach(var r in _records)root.Children.Add(Record(r));LocalStoreHealth health=ConnectionHealthStorage.Inspect();root.Children.Add(H("Diagnostic boundary",21,new(0,20,0,6)));root.Children.Add(Card("Versioned connection-health store",$"State: {health.State}. Results are manual observations only until a separately configured credentialed adapter is approved.","#152437"));Content=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Content=root};}
    private UIElement Capture(){StackPanel p=new();p.Children.Add(H("Plan a connection diagnostic",20));WrapPanel row=new();row.Children.Add(Input("Capability *","health-capability","ConnectionHealth.Capability",_capability,v=>_capability=v,480));row.Children.Add(Input("Owner *","health-owner","ConnectionHealth.Owner",_owner,v=>_owner=v,480));p.Children.Add(row);WrapPanel choices=new();choices.Children.Add(Choice("Environment","ConnectionHealth.Environment",Enum.GetValues<ConfigurationEnvironment>(),_environment,v=>_environment=v,480));choices.Children.Add(Choice("Check kind","ConnectionHealth.Kind",Enum.GetValues<ConnectionCheckKind>(),_kind,v=>_kind=v,480));p.Children.Add(choices);p.Children.Add(Input("Secret reference name (optional)","health-secret-reference","ConnectionHealth.SecretReference",_reference,v=>_reference=v,970));p.Children.Add(Input("Notes","health-notes","ConnectionHealth.Notes",_notes,v=>_notes=v,970));Button add=Btn("Add diagnostic plan","ConnectionHealth.Add",false);add.Click+=(_,_)=>Add();p.Children.Add(add);return Panel(p,new(0,14,0,0));}
    private UIElement Record(ConnectionHealthRecord r){StackPanel p=new();DockPanel h=new();TextBlock s=T(Label(r.State),11,"#AFA4FF",FontWeights.SemiBold);DockPanel.SetDock(s,Dock.Right);h.Children.Add(s);h.Children.Add(H(r.Capability,18));p.Children.Add(h);p.Children.Add(T($"{r.Environment} • {r.Kind} • owner: {r.Owner}",12,"#A9B6CA"));p.Children.Add(T(r.SecretReferenceName.Length==0?"Reference: not configured":$"Reference: {r.SecretReferenceName} (name only)",13,"#E7ECF4",FontWeights.SemiBold));p.Children.Add(T($"Observation: {r.Observation}",12,"#C2CDDC"));WrapPanel a=new();foreach(var x in new[]{ConnectionHealthState.Passed,ConnectionHealthState.Degraded,ConnectionHealthState.Failed,ConnectionHealthState.Blocked}){ConnectionHealthState state=x;Button b=Btn($"Record {Label(state).ToLowerInvariant()}",$"ConnectionHealth.Observe.{state}.{r.Id:N}",true);b.Click+=(_,_)=>Observe(r,state);a.Children.Add(b);}p.Children.Add(a);return Panel(p,new(0,8,0,0));}
    private void Add(){ConnectionHealthDraft d=new(_capability,_owner,_environment,_kind,_reference,_notes);FormValidationResult v=ConnectionHealthService.Validate(d);_issues=v.Issues;if(!v.IsValid){_problem=new("connection-health-validation-failed","Review the diagnostic fields","No plan was added because the fields are invalid or appear to contain a secret.","Remove secret values and correct the highlighted fields.",true);Render();return;}try{var r=ConnectionHealthService.Create(d,DateTimeOffset.UtcNow);var c=_records.Append(r).ToList();ConnectionHealthStorage.Save(c);_records=c;_capability=_owner=_reference=_notes="";_issues=[];_problem=null;_notice="Added diagnostic metadata without running a connection.";Render();}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or JsonException or InvalidDataException){_problem=UserFacingProblemFactory.FromException(ex,"save connection health");Render();}}
    private void Observe(ConnectionHealthRecord r,ConnectionHealthState state){try{string detail=state==ConnectionHealthState.Passed?"Owner recorded a successful credentialed check.":state==ConnectionHealthState.Degraded?"Owner recorded a degraded credentialed check.":state==ConnectionHealthState.Failed?"Owner recorded a failed credentialed check.":"Credentialed adapter is not configured.";var x=ConnectionHealthService.RecordObservation(r,state,detail,DateTimeOffset.UtcNow);var c=_records.Select(v=>v.Id==r.Id?x:v).ToList();ConnectionHealthStorage.Save(c);_records=c;_notice=$"Recorded {Label(state).ToLowerInvariant()} as an explicit manual observation.";_problem=null;Render();}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or JsonException or InvalidDataException or ArgumentException){_problem=UserFacingProblemFactory.FromException(ex,"record connection health");Render();}}
    private UIElement Input(string l,string f,string id,string val,Action<string> ch,double w){StackPanel p=new(){Width=w,Margin=new(0,7,10,0)};p.Children.Add(T(l,12,"#C7D2E3",FontWeights.SemiBold));TextBox x=new(){Text=val,MinHeight=38,Background=B("#101827"),Foreground=Brushes.White,BorderBrush=B("#3A4B66"),Padding=new(10,7,10,7)};AutomationProperties.SetAutomationId(x,id);x.TextChanged+=(_,_)=>ch(x.Text);p.Children.Add(x);string e=string.Join(" ",_issues.Where(i=>i.FieldId==f).Select(i=>i.Message));if(e.Length>0)p.Children.Add(T(e,11,"#FF7788",FontWeights.SemiBold));return p;}
    private static UIElement Choice<TValue>(string l,string id,IReadOnlyList<TValue> vals,TValue sel,Action<TValue> ch,double w)where TValue:struct{StackPanel p=new(){Width=w,Margin=new(0,7,10,0)};p.Children.Add(T(l,12,"#C7D2E3",FontWeights.SemiBold));ComboBox x=new(){ItemsSource=vals,SelectedItem=sel,MinHeight=38};AutomationProperties.SetAutomationId(x,id);x.SelectionChanged+=(_,_)=>{if(x.SelectedItem is TValue v)ch(v);};p.Children.Add(x);return p;}
    private static string Label(ConnectionHealthState s)=>s switch{ConnectionHealthState.NotConfigured=>"NOT CONFIGURED",ConnectionHealthState.ReadyForCredentialedTest=>"READY FOR CREDENTIALED TEST",_=>s.ToString().ToUpperInvariant()};
    private static Border Problem(UserFacingProblem x){StackPanel p=new();p.Children.Add(H($"{x.Title} ({x.Code})",16));p.Children.Add(T(x.Detail,12,"#E1E7F0"));p.Children.Add(T($"Next: {x.RecoveryAction}",12,"#C5AECF"));return new(){Background=B("#251925"),BorderBrush=B("#C95F75"),BorderThickness=new(1),CornerRadius=new(9),Padding=new(15),Margin=new(0,12,0,0),Child=p};}private static Button Btn(string l,string id,bool s){Button b=new(){Content=l,Background=B(s?"#25334A":"#315E91"),Foreground=Brushes.White,Padding=new(14,7,14,7),Margin=new(0,8,8,0)};AutomationProperties.SetAutomationId(b,id);return b;}private static Border Metric(string l,string v,string d){StackPanel p=new();p.Children.Add(T(l,11,"#9EACC0"));p.Children.Add(T(v,22,"#FFFFFF",FontWeights.SemiBold));p.Children.Add(T(d,11,"#9EACC0"));return new(){Width=230,MinHeight=100,Background=B("#151F30"),BorderBrush=B("#31445F"),BorderThickness=new(1),CornerRadius=new(9),Padding=new(14),Margin=new(0,0,10,10),Child=p};}private static Border Card(string h,string t,string bg){StackPanel p=new();p.Children.Add(H(h,16));p.Children.Add(T(t,12,"#C2CDDC"));return new(){Background=B(bg),BorderBrush=B("#31445F"),BorderThickness=new(1),CornerRadius=new(9),Padding=new(16),Margin=new(0,8,0,0),Child=p};}private static Border Panel(UIElement x,Thickness m)=>new(){Background=B("#151F30"),BorderBrush=B("#31445F"),BorderThickness=new(1),CornerRadius=new(9),Padding=new(16),Margin=m,Child=x};private static TextBlock H(string t,double s,Thickness?m=null)=>new(){Text=t,FontSize=s,FontWeight=FontWeights.SemiBold,Foreground=Brushes.White,TextWrapping=TextWrapping.Wrap,Margin=m??new(0,0,0,4)};private static TextBlock T(string t,double s,string c,FontWeight?w=null)=>new(){Text=t,FontSize=s,FontWeight=w??FontWeights.Normal,Foreground=B(c),TextWrapping=TextWrapping.Wrap,Margin=new(0,3,0,0)};private static SolidColorBrush B(string v)=>new((Color)ColorConverter.ConvertFromString(v));
}
